from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class AccountInformation(SchemaObject):
    password_expiration_date = SchemaField(name='passwordExpirationDate')

    def __init__(self, password_expiration_date):
        self.password_expiration_date = password_expiration_date

        super(AccountInformation, self).__init__()
